int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> arr(n);
    for (int& x : arr) cin >> x;

    sort(arr.begin(), arr.end());

    int d = arr.back() - arr.front();
    if (d == 0) {
        cout << 0;
        return 0;
    }

    while (d % 2 == 0) {
        d /= 2;
    }

    for (int x : arr) {
        if ((arr.back() - x) % d != 0) {
            cout << -1;
            return 0;
        }
    }

    cout << d;
    return 0;
}

